import{_ as t,o as a,c as s,a5 as r}from"./chunks/framework.C6epSejR.js";const u=JSON.parse('{"title":"Operating System Project","description":"Extending a basic OS skeleton with user programs, thread scheduling, synchronization, and a file system redesign.","frontmatter":{"title":"Operating System Project","date":"2026-01-15T00:00:00.000Z","description":"Extending a basic OS skeleton with user programs, thread scheduling, synchronization, and a file system redesign."},"headers":[],"relativePath":"blog/os-project.md","filePath":"blog/os-project.md","lastUpdated":1795558112000}'),i={name:"blog/os-project.md"};function o(l,e,n,d,c,h){return a(),s("div",null,[...e[0]||(e[0]=[r('<p class="post-eyebrow">// design doc · systems</p><h1 id="operating-system-project" tabindex="-1">Operating System Project <a class="header-anchor" href="#operating-system-project" aria-label="Permalink to &quot;Operating System Project&quot;">​</a></h1><p class="post-lede">Extending a basic OS skeleton with user programs, thread scheduling, synchronization, and a file system redesign.</p><div class="readouts"><div><b>3.76×</b><span>file system speedup vs FAT</span></div><div><b>1,488</b><span>user threads in one stress run</span></div><div><b>~5×</b><span>throughput with buffer cache</span></div></div><p><a href="https://github.com/CleverAutoman/os-systems-project" target="_blank" rel="noreferrer">Source on GitHub</a></p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>This project extends a basic OS skeleton with three major subsystems: <strong>user programs (processes &amp; syscalls)</strong>, <strong>thread scheduling and synchronization</strong>, and a <strong>file system redesign</strong> featuring an FFS-style layout and a Clock/Second-Chance buffer cache.</p><p>The primary focus is <strong>correctness under concurrency</strong>, <strong>robust resource cleanup</strong>, and <strong>measurable performance improvements</strong>, validated through stress tests and microbenchmarks.</p><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><h3 id="_1-user-programs-processes-syscalls" tabindex="-1">1. User Programs (Processes &amp; Syscalls) <a class="header-anchor" href="#_1-user-programs-processes-syscalls" aria-label="Permalink to &quot;1. User Programs (Processes &amp; Syscalls)&quot;">​</a></h3><h4 id="argument-passing" tabindex="-1">Argument Passing <a class="header-anchor" href="#argument-passing" aria-label="Permalink to &quot;Argument Passing&quot;">​</a></h4><ul><li>Implemented user stack setup with System V–style <code>argc/argv</code> layout.</li><li>Ensured <strong>16-byte stack alignment</strong> to satisfy calling convention requirements.</li></ul><h4 id="multi-process-syscalls" tabindex="-1">Multi-process Syscalls <a class="header-anchor" href="#multi-process-syscalls" aria-label="Permalink to &quot;Multi-process Syscalls&quot;">​</a></h4><ul><li>Implemented <code>exec</code>, <code>wait</code>, <code>fork</code>, and <code>exit</code>, including parent–child synchronization.</li><li>Passed process-tree stress tests: <ul><li><strong>fork_tree</strong>: reached <code>depth=3, fanout=4</code>, creating <strong>84 child processes</strong> in a single run; <strong>148 total processes</strong> across all test cases, with correct exit-status propagation.</li><li><strong>multi-oom-mt</strong> (resource exhaustion + crash recovery): achieved <strong>34 recursive exec depth</strong> consistently across <strong>10 repetitions</strong>, correctly terminating crashed children and reclaiming all kernel resources.</li></ul></li></ul><h4 id="file-related-syscalls" tabindex="-1">File-related Syscalls <a class="header-anchor" href="#file-related-syscalls" aria-label="Permalink to &quot;File-related Syscalls&quot;">​</a></h4><ul><li>Implemented file syscalls including <code>create</code>, <code>remove</code>, <code>tell</code>, <code>open</code>, <code>read</code>, <code>write</code>, and <code>close</code>.</li><li>Designed an <strong>O(1) bitmap-based file descriptor table</strong> to efficiently locate free slots for new descriptors.</li></ul><h3 id="_2-threading-scheduling-synchronization" tabindex="-1">2. Threading, Scheduling &amp; Synchronization <a class="header-anchor" href="#_2-threading-scheduling-synchronization" aria-label="Permalink to &quot;2. Threading, Scheduling &amp; Synchronization&quot;">​</a></h3><h4 id="scheduling-policy" tabindex="-1">Scheduling Policy <a class="header-anchor" href="#scheduling-policy" aria-label="Permalink to &quot;Scheduling Policy&quot;">​</a></h4><ul><li>Implemented <strong>strict priority scheduling</strong>.</li><li>Added <strong>priority donation</strong>, including chained donation, to prevent priority inversion under lock contention.</li></ul><h4 id="synchronization-primitives" tabindex="-1">Synchronization Primitives <a class="header-anchor" href="#synchronization-primitives" aria-label="Permalink to &quot;Synchronization Primitives&quot;">​</a></h4><ul><li>Implemented core primitives: <ul><li><code>semaphore</code></li><li><code>lock</code></li><li><code>condition variable (condvar)</code></li></ul></li><li>Ensured correctness under preemption and priority-aware scheduling.</li></ul><h4 id="user-threads-pthread-like-api" tabindex="-1">User Threads (pthread-like API) <a class="header-anchor" href="#user-threads-pthread-like-api" aria-label="Permalink to &quot;User Threads (pthread-like API)&quot;">​</a></h4><ul><li>Implemented user thread syscalls including <code>pthread_create</code>, <code>pthread_join</code>, and <code>pthread_exit</code>.</li><li>Adopted a <strong>one-to-one threading model</strong> instead of green threads to avoid process-wide blocking during I/O.</li><li>Passed recursive multithreaded stress test (<strong>search-arr</strong>): <ul><li>Each search spawns <strong>31 threads</strong> (binary recursion over 16 elements).</li><li><strong>48 searches</strong>, creating <strong>1,488 threads</strong> total, validating per-thread user stacks, join semantics, and shared address-space behavior.</li></ul></li></ul><h3 id="_3-file-system" tabindex="-1">3. File System <a class="header-anchor" href="#_3-file-system" aria-label="Permalink to &quot;3. File System&quot;">​</a></h3><p>Replaced the original list-based FAT design with an <strong>FFS-style indexed allocation</strong> scheme and added a <strong>buffer cache</strong> using the <strong>Second-Chance Clock</strong> eviction algorithm.</p><h4 id="fast-file-system-ffs-style" tabindex="-1">Fast File System (FFS-style) <a class="header-anchor" href="#fast-file-system-ffs-style" aria-label="Permalink to &quot;Fast File System (FFS-style)&quot;">​</a></h4><ul><li>Implemented indexed allocation using direct, indirect, and doubly indirect blocks, replacing list-based FAT traversal.</li><li>Supports files up to approximately <strong>8 MB</strong> (512-byte blocks).</li><li>Added <strong>lazy allocation and lazy loading</strong> for sparse file growth to reduce unnecessary disk I/O.</li></ul><h4 id="performance-evaluation-ffs-vs-fat" tabindex="-1">Performance Evaluation (FFS vs FAT) <a class="header-anchor" href="#performance-evaluation-ffs-vs-fat" aria-label="Permalink to &quot;Performance Evaluation (FFS vs FAT)&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Workload</th><th>Microbenchmark</th><th style="text-align:right;">FAT (ticks)</th><th style="text-align:right;">FFS (ticks)</th><th style="text-align:right;">Improvement</th><th style="text-align:right;">Speedup</th></tr></thead><tbody><tr><td>Sequential create + sequential read</td><td><code>100B file × 200 loops</code></td><td style="text-align:right;">2183</td><td style="text-align:right;">980</td><td style="text-align:right;">55.1%</td><td style="text-align:right;"><strong>2.23×</strong></td></tr><tr><td>Sequential create + sequential read</td><td><code>50B file × 400 loops</code></td><td style="text-align:right;">7736</td><td style="text-align:right;">3040</td><td style="text-align:right;">60.7%</td><td style="text-align:right;"><strong>2.54×</strong></td></tr><tr><td>Sequential create + random directory read</td><td><code>100B file × 200 loops</code></td><td style="text-align:right;">3364</td><td style="text-align:right;">963</td><td style="text-align:right;">71.4%</td><td style="text-align:right;"><strong>3.49×</strong></td></tr><tr><td>Sequential create + random directory read</td><td><code>50B file × 400 loops</code></td><td style="text-align:right;">7472</td><td style="text-align:right;">1988</td><td style="text-align:right;">73.4%</td><td style="text-align:right;"><strong>3.76×</strong></td></tr></tbody></table><p>The random directory read workload stresses directory locality.</p><div class="tip custom-block"><p class="custom-block-title">Key findings</p><ol><li><strong>FFS consistently outperforms FAT across both sequential and random workloads</strong>, achieving speedups ranging from <strong>2.23× to 3.76×</strong>.</li><li><strong>Small-file access benefits most from FFS-style indexed allocation</strong>, indicating more efficient handling of small-file metadata.</li><li><strong>Random access over small files yields the largest overall speedup</strong>, highlighting improved directory locality and metadata organization.</li></ol></div><h4 id="buffer-cache-second-chance-clock" tabindex="-1">Buffer Cache (Second-Chance Clock) <a class="header-anchor" href="#buffer-cache-second-chance-clock" aria-label="Permalink to &quot;Buffer Cache (Second-Chance Clock)&quot;">​</a></h4><ul><li>Implemented a block buffer cache with <strong>Second-Chance Clock</strong> replacement.</li><li>Concurrency design: <ul><li>A <strong>global lock</strong> protects cache-wide metadata.</li><li><strong>Per-entry locks</strong> protect individual cache blocks.</li><li>A <code>busy</code> flag is used to avoid holding the global lock while waiting, reducing contention under concurrent access.</li></ul></li><li>Used a handle-based interface to enable <strong>kernel-level zero-copy–style access</strong> and reduce unnecessary memory copying.</li></ul><h5 id="performance-evaluation-buffer-cache" tabindex="-1">Performance Evaluation (Buffer Cache) <a class="header-anchor" href="#performance-evaluation-buffer-cache" aria-label="Permalink to &quot;Performance Evaluation (Buffer Cache)&quot;">​</a></h5><p>Under a repeated small I/O and metadata-heavy workload (<code>100B accesses × 200 loops</code>), enabling the buffer cache significantly reduced disk I/O by serving most requests directly from memory.</p><table tabindex="0"><thead><tr><th>Configuration</th><th style="text-align:right;">Time (ticks)</th><th>Result</th></tr></thead><tbody><tr><td>Cache OFF</td><td style="text-align:right;">~983</td><td>baseline</td></tr><tr><td>Cache ON (global lock)</td><td style="text-align:right;">~188</td><td><strong>~80–82% latency reduction</strong>, <strong>~5× throughput</strong></td></tr><tr><td>Cache ON (per-entry lock + <code>busy</code> condvar)</td><td style="text-align:right;">~203</td><td>slightly slower in single-threaded runs</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Key findings</p><ul><li>The global-lock buffer cache achieves the best performance under Pintos&#39; <strong>single-threaded</strong> execution model.</li><li>The per-entry lock design is more scalable for concurrent workloads, but its extra locking and condition-variable overhead provides no benefit in the single-threaded case.</li><li>Therefore, the <strong>global-lock design</strong> was chosen as the final implementation for optimal performance and simplicity.</li></ul></div><h2 id="validation-stress-tests" tabindex="-1">Validation &amp; Stress Tests <a class="header-anchor" href="#validation-stress-tests" aria-label="Permalink to &quot;Validation &amp; Stress Tests&quot;">​</a></h2><ul><li>Process &amp; syscalls: <code>fork_tree</code>, <code>multi-oom-mt</code></li><li>User threads: <code>search-arr</code></li><li>Additional correctness tests from the basic test suite</li></ul><h2 id="key-design-decisions" tabindex="-1">Key Design Decisions <a class="header-anchor" href="#key-design-decisions" aria-label="Permalink to &quot;Key Design Decisions&quot;">​</a></h2><ul><li>Prioritized correctness and deterministic behavior, especially for: <ul><li><code>wait</code> semantics</li><li>crash handling</li><li>resource cleanup paths</li></ul></li><li>Designed for robustness under failure: <ul><li>syscall failures do not panic the kernel</li><li>abnormal process termination does not leak kernel resources</li></ul></li><li>Integrated priority-aware scheduling and donation across all synchronization primitives.</li></ul><h2 id="challenges-lessons-learned" tabindex="-1">Challenges &amp; Lessons Learned <a class="header-anchor" href="#challenges-lessons-learned" aria-label="Permalink to &quot;Challenges &amp; Lessons Learned&quot;">​</a></h2><ul><li>Kernel subsystems require well-defined invariants before implementation (process/thread lifecycles, ownership, and cleanup).</li><li>Incremental development significantly reduces debugging complexity in OS projects.</li><li>Fine-grained commits and continuous testing are critical for maintaining kernel stability.</li></ul>',43)])])}const p=t(i,[["render",o]]);export{u as __pageData,p as default};
